<?php require_once __DIR__.'/includes/functions.php';$admin=require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$editing=$id>0;$errors=[];$item=['name'=>'','email'=>'','role_id'=>2];if($editing){$stmt=db()->prepare('SELECT id,name,email,role_id FROM users WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){http_response_code(404);exit('User not found.');}}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$role=(int)($_POST['role_id']??2);$item=['name'=>$name,'email'=>$email,'role_id'=>$role];if(!valid_name($name))$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Invalid email.';if(!in_array($role,[1,2],true))$errors[]='Invalid role.';if(!$editing && !valid_password($password))$errors[]='Password must be 8–72 characters.';if($editing && $password!=='' && !valid_password($password))$errors[]='Password must be 8–72 characters.';if($editing && $id===(int)$admin['id'] && $role!==1)$errors[]='You cannot remove your own administrator role.';if(!$errors){try{if($editing){$hash=$password!==''?password_hash($password,PASSWORD_DEFAULT):null;$stmt=db()->prepare('UPDATE users SET name=?,email=?,role_id=?,password_hash=COALESCE(?,password_hash) WHERE id=?');$stmt->execute([$name,$email,$role,$hash,$id]);}else{$stmt=db()->prepare('INSERT INTO users(name,email,password_hash,role_id) VALUES (?,?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);}flash('success',$editing?'User updated.':'User created.');redirect('users.php');}catch(PDOException $ex){if($ex->getCode()==='23000')$errors[]='Email is already in use.';else throw $ex;}}}page_start($editing?'Edit user':'Add user');?><section class="page-head"><span class="eyebrow">ADMINISTRATION</span><h1><?=$editing?'Edit user':'Add a new user'?></h1></section><div class="panel narrow"><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><form method="post" class="stack"><?=csrf_field()?><label>Name<input name="name" maxlength="100" required value="<?=e($item['name'])?>"></label><label>Email<input type="email" name="email" required value="<?=e($item['email'])?>"></label><label>Password <?= $editing?'<small>(optional; blank keeps current)</small>':'' ?><input type="password" name="password" minlength="8" maxlength="72" <?= $editing?'':'required' ?> autocomplete="new-password"></label><label>Role<select name="role_id"><option value="2" <?= (int)$item['role_id']===2?'selected':'' ?>>User</option><option value="1" <?= (int)$item['role_id']===1?'selected':'' ?>>Admin</option></select></label><div class="actions"><button class="button" type="submit">Save user</button><a class="button secondary" href="<?=e(url('users.php'))?>">Cancel</a></div></form></div><?php page_end(); ?>
